import {
    RESET_REDUX,
    CREATE_MANUFACTURER_QUANTITY_DISCOUNT,
    CREATE_MANUFACTURER_QUANTITY_DISCOUNT_SUCCESS,
    CREATE_MANUFACTURER_QUANTITY_DISCOUNT_FAILED,
    UPDATE_MANUFACTURER_QUANTITY_DISCOUNT,
    UPDATE_MANUFACTURER_QUANTITY_DISCOUNT_SUCCESS,
    UPDATE_MANUFACTURER_QUANTITY_DISCOUNT_FAILED,
    GET_MANUFACTURER_QUANTITY_DISCOUNTS,
    GET_MANUFACTURER_QUANTITY_DISCOUNTS_SUCCESS,
    GET_MANUFACTURER_QUANTITY_DISCOUNTS_FAILED,
    GET_MANUFACTURER_QUANTITY_DISCOUNT_BY_ID,
    GET_MANUFACTURER_QUANTITY_DISCOUNT_BY_ID_SUCCESS,
    GET_MANUFACTURER_QUANTITY_DISCOUNT_BY_ID_FAILED,
} from './constants';

export const resetRedux = () => ({
    type: RESET_REDUX,
});

export const createManufacturerQuantityDiscount = (priceDiscount) => ({
    type: CREATE_MANUFACTURER_QUANTITY_DISCOUNT,
    payload: priceDiscount,
});

export const createManufacturerQuantityDiscountSuccess = (priceDiscount) => ({
    type: CREATE_MANUFACTURER_QUANTITY_DISCOUNT_SUCCESS,
    payload: priceDiscount,
});

export const createManufacturerQuantityDiscountFailed = (message, errors) => ({
    type: CREATE_MANUFACTURER_QUANTITY_DISCOUNT_FAILED,
    payload: { message: message, errors: errors },
});

//Update
export const updateManufacturerQuantityDiscount = (priceDiscount, id) => ({
    type: UPDATE_MANUFACTURER_QUANTITY_DISCOUNT,
    payload: { data: priceDiscount, id: id },
});

export const updateManufacturerQuantityDiscountSuccess = (priceDiscount) => ({
    type: UPDATE_MANUFACTURER_QUANTITY_DISCOUNT_SUCCESS,
    payload: priceDiscount,
});

export const updateManufacturerQuantityDiscountFailed = (message, errors) => ({
    type: UPDATE_MANUFACTURER_QUANTITY_DISCOUNT_FAILED,
    payload: { message: message, errors: errors },
});

export const getManufacturerQuantityDiscounts = () => ({
    type: GET_MANUFACTURER_QUANTITY_DISCOUNTS,
});

export const getManufacturerQuantityDiscountsSuccess = (discounts) => ({
    type: GET_MANUFACTURER_QUANTITY_DISCOUNTS_SUCCESS,
    payload: discounts,
});

export const getManufacturerQuantityDiscountsFailed = (message, errors) => ({
    type: GET_MANUFACTURER_QUANTITY_DISCOUNTS_FAILED,
    payload: { message: message, errors: errors },
});

//Get wholesaler price discount by id

export const getManufacturerQuantityDiscountById = (id) => ({
    type: GET_MANUFACTURER_QUANTITY_DISCOUNT_BY_ID,
    payload: id,
});
export const getManufacturerQuantityDiscountByIdSuccess = (item) => ({
    type: GET_MANUFACTURER_QUANTITY_DISCOUNT_BY_ID_SUCCESS,
    payload: item,
});

export const getManufacturerQuantityDiscountByIdFailed = (message, errors) => ({
    type: GET_MANUFACTURER_QUANTITY_DISCOUNT_BY_ID_FAILED,
    payload: { message: message, errors: errors },
});
