import { tokenConfig } from '../../auth/tokenConfig';
import { all, call, fork, put, takeEvery } from 'redux-saga/effects';
import axios from 'axios';
import {
    updateManufacturerQuantityDiscountSuccess,
    updateManufacturerQuantityDiscountFailed,
    createManufacturerQuantityDiscountFailed,
    createManufacturerQuantityDiscountSuccess,
    getManufacturerQuantityDiscountsSuccess,
    getManufacturerQuantityDiscountsFailed,
    getManufacturerQuantityDiscountByIdSuccess,
    getManufacturerQuantityDiscountByIdFailed,
} from './actions';
import {
    CREATE_MANUFACTURER_QUANTITY_DISCOUNT,
    GET_MANUFACTURER_QUANTITY_DISCOUNTS,
    GET_MANUFACTURER_QUANTITY_DISCOUNT_BY_ID,
    UPDATE_MANUFACTURER_QUANTITY_DISCOUNT,
} from './constants';

function* getManufacturerQuantityDiscounts() {
    const apiCall = () => {
        return axios
            .get('manufacturers/quantity-discounts', tokenConfig())
            .then((response) => response.data)
            .catch((err) => {
                throw err;
            });
    };

    try {
        const response = yield call(apiCall);

        yield put(getManufacturerQuantityDiscountsSuccess(response));
    } catch (error) {
        let message;
        console.log('ERRORS', error.response);
        switch (error.status) {
            case 500:
                message = 'Internal Server Error';
                break;
            case 401:
                message = 'Invalid credentials';
                break;
            default:
                message = error;
        }
        yield put(getManufacturerQuantityDiscountsFailed(message, error.response.data.errors));
    }
}

//Create wholesale price discount
function* createManufacturerQuantityDiscount(payload) {
    console.log('Am here', payload);
    const apiCall = () => {
        return axios
            .post('manufacturers/quantity-discounts/create', payload.payload, tokenConfig())
            .then((response) => response.data)
            .catch((err) => {
                throw err;
            });
    };

    try {
        const response = yield call(apiCall);
        yield put(createManufacturerQuantityDiscountSuccess(response));
    } catch (error) {
        let message;

        console.log('ERRORS', error.response.data);
        switch (error.status) {
            case 500:
                message = 'Internal Server Error';
                break;
            case 401:
                message = 'Invalid credentials';
                break;
            default:
                message = error;
        }
        yield put(createManufacturerQuantityDiscountFailed(message, error.response.data.errors));
    }
}

//Update wholesale variation receipt
function* updateManufacturerQuantityDiscount(payload) {
    const apiCall = () => {
        return axios
            .patch(`manufacturers/quantity-discounts/${payload.payload.id}/update`, payload.payload.data, tokenConfig())
            .then((response) => response.data)
            .catch((err) => {
                throw err;
            });
    };

    try {
        const response = yield call(apiCall);

        yield put(updateManufacturerQuantityDiscountSuccess(response));
    } catch (error) {
        let message;

        console.log('ERRORS', error.response.data);
        switch (error.status) {
            case 500:
                message = 'Internal Server Error';
                break;
            case 401:
                message = 'Invalid credentials';
                break;
            default:
                message = error.response.data.detail;
        }
        yield put(updateManufacturerQuantityDiscountFailed(message, error.response.data.errors));
    }
}

//Get distributor price discount by ID
function* getManufacturerQuantityDiscountById(payload) {
    const apiCall = () => {
        return axios
            .get(`manufacturers/quantity-discounts/${payload.payload}`, tokenConfig())
            .then((response) => response.data)
            .catch((err) => {
                throw err;
            });
    };

    try {
        const response = yield call(apiCall);

        yield put(getManufacturerQuantityDiscountByIdSuccess(response));
    } catch (error) {
        let message;
        switch (error.status) {
            case 500:
                message = 'Internal Server Error';
                break;
            case 401:
                message = 'Invalid credentials';
                break;
            default:
                message = error;
        }
        yield put(getManufacturerQuantityDiscountByIdFailed(message, error.response.data.errors));
    }
}

//Get distributor price discounts
//Get variations
export function* watchGetManufacturerQuantityDiscounts() {
    yield takeEvery(GET_MANUFACTURER_QUANTITY_DISCOUNTS, getManufacturerQuantityDiscounts);
}

//QUANTITY_DISCOUNTS
//Create wholesale receipt
export function* watchCreateManufacturerQuantityDiscount() {
    yield takeEvery(CREATE_MANUFACTURER_QUANTITY_DISCOUNT, createManufacturerQuantityDiscount);
}
//Update wholesale receipt
export function* watchUpdateManufacturerQuantityDiscount() {
    yield takeEvery(UPDATE_MANUFACTURER_QUANTITY_DISCOUNT, updateManufacturerQuantityDiscount);
}

//Update wholesale receipt
export function* watchGetManufacturerQuantityDiscountyById() {
    yield takeEvery(GET_MANUFACTURER_QUANTITY_DISCOUNT_BY_ID, getManufacturerQuantityDiscountById);
}
function* priceDiscountsSaga() {
    yield all([
        fork(watchCreateManufacturerQuantityDiscount),
        fork(watchGetManufacturerQuantityDiscounts),
        fork(watchUpdateManufacturerQuantityDiscount),
        fork(watchGetManufacturerQuantityDiscountyById),
    ]);
}

export default priceDiscountsSaga;
